INSERT INTO `faq` VALUES
('007ed4e4-4115-4234-9fd6-48d1a931476e','Гарантируете ли вы результат?','Мы гарантируем, что с вами будет работать проверенный специалист. Наши экстрасенсы всегда честны в прогнозах.',4,1),
('260c5b8d-e082-4cba-a5a4-cf51e6222b95','С какими проблемами можно обратиться?','Наши экстрасенсы помогают в широком спектре вопросов: любовь, здоровье, бизнес, поиск пропавших и многое другое.',6,1),
('46de5c38-87c8-44c5-9927-a9f645e8e0ee','Как подготовиться к консультации?','Специальной подготовки не требуется. Рекомендуем заранее сформулировать вопросы.',7,1),
('72739b0c-62ed-41d7-af01-5b08751e6378','Сколько стоит консультация экстрасенса?','Стоимость зависит от специалиста и формата проведения. Первичная консультация длится 60 минут. Точную стоимость уточняйте у администратора.',2,1),
('7f673e47-d455-4027-a57c-375c73e34653','Конфиденциальна ли информация?','Абсолютно. Мы строго соблюдаем конфиденциальность всех обращений.',5,1),
('9bfe8e6a-53fe-4169-892c-c82fa55688d6','Можно ли получить консультацию онлайн?','Да, большинство специалистов проводят консультации как очно, так и онлайн.',3,1),
('b18f7c38-7fa8-4e77-a3c0-155737cb6b65','Все ли участники — настоящие экстрасенсы?','Все специалисты прошли строгий отбор и подтвердили свои способности.',8,1),
('ce7f6759-ac47-43ac-ac56-28b65d1f8131','Как записаться на приём к экстрасенсу?','Для записи на приём заполните форму на нашем сайте, указав ваше имя, телефон и краткое описание ситуации. Наш администратор свяжется с вами в течение 24 часов.',1,1);
/*!40000 ALTER TABLE `faq` ENABLE KEYS */;
UNLOCK TABLES;

