INSERT INTO `pages` VALUES
('0faf07f4-6959-43ee-9516-a78e51ef902c','service-finansovaya-magiya','{\"title\":\"Финансовая магия\",\"description\":\"Финансовая магия — это комплекс энергетических практик, направленных на улучшение материального положения.\",\"directions_title\":\"Направления финансовой магии\",\"directions\":\"Привлечение желаемой профессии\\nУвеличение заработка\\nПриумножение финансовых ресурсов\\nОткрытие денежного потока\\nСнятие финансовых блоков\\nЗащита бизнеса\",\"situations_title\":\"Когда стоит обратиться\",\"situations\":\"Хронические финансовые трудности\\nПостоянная потеря денег\\nНевозможность найти работу\\nБизнес не приносит прибыли\\nДолги растут\",\"how_it_works_title\":\"Как проходит консультация\",\"how_it_works\":\"Анализ ситуации\\nДиагностика денежных потоков\\nВыявление блоков\\nСоставление плана\\nПроведение ритуалов\\nРекомендации\",\"results_title\":\"Что вы получите\",\"results\":\"Устранение энергетических блоков\\nАктивизацию денежного потока\\nЗащиту финансов\\nРекомендации по поддержанию достатка\",\"cta_title\":\"Хотите улучшить положение?\",\"cta_text\":\"Запишитесь на консультацию.\",\"cta_button\":\"Получить консультацию\"}','2026-03-06 12:45:32'),
('2ccb80da-de89-4975-9ad9-af1513280dd9','booking','{\"page_title\":\"Запись на приём к экстрасенсу\",\"page_subtitle\":\"Заполните форму для записи на консультацию\"}','2026-03-06 12:45:32'),
('3a39e3bb-9c33-4d2e-b2e6-2d14526f9b8b','topic-venets-bezbrachiya','{\"title\":\"Венец безбрачия\",\"description\":\"Венец безбрачия — это энергетическая блокировка, которая препятствует созданию семьи.\",\"symptoms_title\":\"Признаки венца безбрачия\",\"symptoms\":\"Отношения заканчиваются одинаково\\nНет серьёзных отношений после 30\\nСвадьбы отменяются\\nПривлекаете неподходящих партнёров\",\"when_title\":\"Когда нужна помощь\",\"when_to_contact\":\"Если личная жизнь не складывается годами\\nЕсли в роду есть одинокие люди\",\"consultation_title\":\"Работа с венцом безбрачия\",\"consultation_process\":\"Диагностика\\nОпределение причины\\nСнятие блокировки\\nВосстановление способности любить\",\"cta_title\":\"Готовы к переменам?\",\"cta_text\":\"Запишитесь на консультацию.\",\"cta_button\":\"Снять венец безбрачия\"}','2026-03-06 12:45:32'),
('3afa21cd-9420-4e69-905f-95eea877c506','topic-sglaz','{\"title\":\"Сглаз\",\"description\":\"Сглаз — это непреднамеренное негативное воздействие, вызванное завистью или сильными эмоциями.\",\"symptoms_title\":\"Симптомы сглаза\",\"symptoms\":\"Внезапная усталость\\nГоловные боли\\nРезкая смена настроения\\nПроблемы со сном\\nНеудачи в делах\",\"when_title\":\"Когда обращаться\",\"when_to_contact\":\"Если негатив появился после похвалы\\nЕсли успехи сменились неудачами\",\"consultation_title\":\"Снятие сглаза\",\"consultation_process\":\"Диагностика\\nСнятие воздействия\\nВосстановление энергетики\\nУстановка защиты\",\"cta_title\":\"Чувствуете что-то не то?\",\"cta_text\":\"Запишитесь на диагностику.\",\"cta_button\":\"Снять сглаз\"}','2026-03-06 12:45:32'),
('41b48204-191e-41ec-bb22-766ed815f20b','service-magiya-zhizni','{\"title\":\"Магия жизни\",\"description\":\"Магия жизни — это широкий спектр энергетических практик, направленных на улучшение качества жизни.\",\"directions_title\":\"Направления\",\"directions\":\"Улучшение качества жизни\\nИзбавление от зависимостей\\nСнятие блоков\\nВосстановление энергии\\nОбретение гармонии\\nКармическая работа\",\"situations_title\":\"Когда обращаются\",\"situations\":\"Ощущение тупика\\nХроническая усталость\\nЗависимости\\nПотеря мотивации\\nТревожность\",\"how_it_works_title\":\"Как проходит консультация\",\"how_it_works\":\"Беседа\\nДиагностика\\nВыявление причин\\nСоставление плана\\nЭнергетические практики\\nРекомендации\",\"results_title\":\"Что вы получите\",\"results\":\"Восстановление энергии\\nОсвобождение от блоков\\nПомощь с зависимостями\\nГармонизацию состояния\",\"cta_title\":\"Готовы к переменам?\",\"cta_text\":\"Запишитесь на консультацию.\",\"cta_button\":\"Получить консультацию\"}','2026-03-06 12:45:32'),
('6be37ade-44c8-4b29-b683-5d156f380ec2','topic-zaklyatie','{\"title\":\"Заклятие\",\"description\":\"Заклятие — это мощное магическое воздействие, закрепляющее программу в судьбе человека.\",\"symptoms_title\":\"Признаки заклятия\",\"symptoms\":\"Хроническая неудача\\nПовторяющиеся негативные сценарии\\nОщущение «замкнутого круга»\\nБлокировка возможностей\",\"when_title\":\"Когда нужна помощь\",\"when_to_contact\":\"Если проблемы не решаются годами\\nЕсли жизнь остановилась\",\"consultation_title\":\"Работа с заклятием\",\"consultation_process\":\"Глубокая диагностика\\nОпределение типа\\nПоэтапная работа по снятию\\nЗакрепление результата\",\"cta_title\":\"Чувствуете блокировку?\",\"cta_text\":\"Запишитесь на консультацию.\",\"cta_button\":\"Снять заклятие\"}','2026-03-06 12:45:32'),
('7f8d8f90-07be-4fef-8055-3dbe503be7be','contacts','{\"page_title\":\"Контакты\",\"page_subtitle\":\"Свяжитесь с нами для записи на консультацию\"}','2026-03-06 12:45:32'),
('84b1df2b-a4dd-4857-a158-3d21adb4eab0','home','{\"hero_h1\":\"Помощь сильнейших экстрасенсов, ясновидящих, целителей, магов\",\"hero_subtitle\":\"Сайт помощи экстрасенсов\",\"hero_logo_bitva_url\":\"https://customer-assets.emergentagent.com/job_f7eeb759-9e5b-4f73-9fda-0f824d4e9d83/artifacts/m73lgvkc_bitva.png\",\"hero_logo_bitva_alt\":\"Битва экстрасенсов\",\"hero_logo_bitva_height_desktop\":64,\"hero_logo_bitva_height_mobile\":48,\"hero_logo_tnt_url\":\"https://customer-assets.emergentagent.com/job_f7eeb759-9e5b-4f73-9fda-0f824d4e9d83/artifacts/yyhafsf8_tnt.png\",\"hero_logo_tnt_alt\":\"ТНТ\",\"hero_logo_tnt_height_desktop\":64,\"hero_logo_tnt_height_mobile\":48,\"hero_unique\":\"Уникальная возможность!\",\"hero_text1\":\"Лично обратиться к любому участнику проекта «Битва экстрасенсов».\",\"hero_text2\":\"И получить диагностику и консультацию экстрасенсов, ясновидящих, магов, целителей\",\"hero_subheading\":\"помощь и консультация экстрасенса\",\"about_text\":\"Вам лично помогут сильнейшие и самые лучшие экстрасенсы России решить ваши проблемы и получить ответы на ваши вопросы. Экстрасенсы нашего проекта обладают уникальными способностями, которые были подтверждены на всю страну в рамках одного из самых известных телевизионных шоу.\",\"cta_text\":\"Количество заявок на помощь ограничено!\",\"cta_button\":\"Получить помощь экстрасенса!\",\"cta_subtext\":\"Не упустите свой шанс!\",\"participants_title\":\"Лучшие экстрасенсы России\",\"benefits_title\":\"Почему выбирают нас\",\"services_title\":\"Услуги экстрасенсов\",\"service_cat_1\":\"Финансовая магия\\nЖелаемая профессия\\nУвеличение заработка\\nПриумножение финансовых ресурсов\\nОткрытие денежного потока\\nСнятие блоков с финансовых потоков\",\"service_cat_2\":\"Любовная магия\\nВозврат любимого человека\\nУкрепление семейных уз\\nПривлечение второй половины\\nОбряды на красоту и молодость\\nРитуалы на гармонию в отношениях\",\"service_cat_3\":\"Магия жизни\\nУлучшение качества жизни\\nИзбавление от зависимостей\\nСнятие блоков и негативных программ\\nВосстановление мужской и женской энергии\\nОбретение внутренней гармонии\",\"service_cat_4\":\"Магическая защита\\nАвторские защиты и обереги\\nРунические амулеты\\nРитуалы на защиту семьи\\nЗащита имущества и финансов\\nЗаговоры на удачу и благополучие\",\"reviews_title\":\"Отзывы\",\"form_title\":\"Запишитесь на консультацию\",\"form_subtitle\":\"Заполните форму и мы свяжемся с вами в ближайшее время\",\"seo_text_title\":\"Экстрасенс онлайн — возможность изменить вашу жизнь\",\"seo_text\":\"Официальный сайт помощи экстрасенсов — это ваш надёжный путь к получению квалифицированной помощи от сильнейших экстрасенсов России.\\n\\nЕсли вы ищете помощь экстрасенса, консультацию ясновидящего или услуги медиума — вы обратились по адресу.\\n\\nЗапись на приём к экстрасенсу осуществляется через удобную онлайн-форму.\"}','2026-03-06 12:45:32'),
('90bef367-e41c-4606-a410-b1dc94cdf875','reviews','{\"page_title\":\"Отзывы о наших специалистах\",\"page_subtitle\":\"Реальные истории людей, которым мы помогли\"}','2026-03-06 12:45:32'),
('9f539278-89ca-4a96-8c20-1d2169e2c799','topic-privorot','{\"title\":\"Приворот\",\"description\":\"Приворот — это магическое воздействие, направленное на привлечение чувств определённого человека.\",\"symptoms_title\":\"Признаки приворота\",\"symptoms\":\"Навязчивые мысли об одном человеке\\nПотеря интереса к другим\\nРезкое изменение чувств\\nЗависимость от партнёра\",\"when_title\":\"Когда обращаться\",\"when_to_contact\":\"Если подозреваете приворот\\nЕсли чувства изменились внезапно\",\"consultation_title\":\"Диагностика и помощь\",\"consultation_process\":\"Диагностика\\nОпределение типа воздействия\\nСнятие приворота\\nВосстановление состояния\",\"cta_title\":\"Нужна помощь?\",\"cta_text\":\"Запишитесь на диагностику.\",\"cta_button\":\"Снять приворот\"}','2026-03-06 12:45:32'),
('c25a55ea-3f33-402d-a957-07823c6ad225','participants','{\"page_title\":\"Лучшие экстрасенсы России\",\"page_subtitle\":\"Сильнейшие экстрасенсы, медиумы, ясновидящие, маги и целители\"}','2026-03-06 12:45:32'),
('c2fcbb44-443b-4cba-a4af-9dc1da4f6c7c','service-magicheskaya-zashchita','{\"title\":\"Магическая защита\",\"description\":\"Магическая защита — это система ритуалов, направленных на создание защитного поля.\",\"directions_title\":\"Направления\",\"directions\":\"Авторские защиты и обереги\\nРунические амулеты\\nРитуалы на защиту семьи\\nЗащита имущества и финансов\\nЗаговоры на удачу\\nЗащита бизнеса\",\"situations_title\":\"Когда нужна защита\",\"situations\":\"После снятия порчи\\nПри ощущении зависти\\nПеред важными событиями\\nДля защиты детей\\nПосле серии неудач\",\"how_it_works_title\":\"Как проводится защита\",\"how_it_works\":\"Диагностика состояния\\nВыявление уязвимостей\\nПодбор метода\\nСоздание оберегов\\nЗащитные ритуалы\\nРекомендации\",\"results_title\":\"Что вы получите\",\"results\":\"Защитный барьер\\nИндивидуальный оберег\\nЗащиту семьи и дома\\nРекомендации по профилактике\",\"cta_title\":\"Хотите защитить себя?\",\"cta_text\":\"Запишитесь на консультацию.\",\"cta_button\":\"Получить консультацию\"}','2026-03-06 12:45:32'),
('cc08bf8c-1ed3-4c56-b157-ccf5cd7ee271','topic-porcha','{\"title\":\"Порча\",\"description\":\"Порча — это целенаправленное негативное воздействие на человека, которое может затрагивать различные сферы его жизни.\\n\\nЕё последствия могут быть серьёзными и затяжными, если вовремя не обратиться за помощью.\",\"symptoms_title\":\"Признаки наличия порчи\",\"symptoms\":\"Резкое ухудшение здоровья без видимых причин\\nПостоянные неудачи в делах\\nРазлад в семье\\nФинансовые проблемы\\nАпатия, депрессия\\nНочные кошмары, бессонница\",\"when_title\":\"Когда стоит обратиться\",\"when_to_contact\":\"Если несколько признаков проявляются одновременно\\nЕсли негатив начался после конфликта\\nЕсли врачи не могут найти причину\",\"consultation_title\":\"Как проходит диагностика\",\"consultation_process\":\"Предварительная беседа\\nДиагностика\\nОпределение типа воздействия\\nСоставление программы помощи\\nПроведение обрядов\\nРекомендации по защите\",\"cta_title\":\"Нужна диагностика?\",\"cta_text\":\"Запишитесь на консультацию.\",\"cta_button\":\"Снять порчу\"}','2026-03-06 12:45:32'),
('d6dfd850-c5fd-4990-a029-4b38426a1933','faq','{\"page_title\":\"Частые вопросы\",\"page_subtitle\":\"Ответы на самые популярные вопросы\"}','2026-03-06 12:45:32'),
('f856f577-07e8-4989-865a-3a449c9456f4','service-lyubovnaya-magiya','{\"title\":\"Любовная магия\",\"description\":\"Любовная магия — это одно из древнейших направлений, помогающее людям обрести счастье в личной жизни.\",\"directions_title\":\"Направления\",\"directions\":\"Возврат любимого\\nУкрепление семейных уз\\nПривлечение партнёра\\nОбряды на красоту\\nРитуалы на гармонию\\nСнятие венца безбрачия\",\"situations_title\":\"Когда стоит обратиться\",\"situations\":\"Партнёр ушёл\\nОтношения разрушаются\\nНе удаётся встретить партнёра\\nОхлаждение чувств\",\"how_it_works_title\":\"Как проходит работа\",\"how_it_works\":\"Беседа\\nДиагностика отношений\\nВыявление причин\\nРазработка стратегии\\nПроведение ритуалов\\nРекомендации\",\"results_title\":\"Что вы получите\",\"results\":\"Восстановление чувств\\nГармонизацию отношений\\nЗащиту отношений\\nПомощь в привлечении партнёра\",\"cta_title\":\"Хотите наладить личную жизнь?\",\"cta_text\":\"Запишитесь на консультацию.\",\"cta_button\":\"Получить консультацию\"}','2026-03-06 12:45:32'),
('fe1c6081-b0b5-43bb-90d2-fccca418ecbd','topic-proklyatie','{\"title\":\"Проклятие\",\"description\":\"Проклятие — это сильное негативное воздействие, которое может передаваться из поколения в поколение.\",\"symptoms_title\":\"Признаки родового проклятия\",\"symptoms\":\"Повторяющиеся несчастья в нескольких поколениях\\nОдинаковые болезни у родственников\\nНевозможность создать семью\\nРанние смерти в роду\",\"when_title\":\"Когда нужна помощь\",\"when_to_contact\":\"Если вы заметили закономерности в судьбах родственников\\nЕсли проблемы повторяются из поколения в поколение\",\"consultation_title\":\"Работа с проклятием\",\"consultation_process\":\"Изучение истории рода\\nДиагностика\\nСнятие проклятия\\nУстановка защиты\",\"cta_title\":\"Хотите разорвать цепь?\",\"cta_text\":\"Запишитесь на консультацию.\",\"cta_button\":\"Снять проклятие\"}','2026-03-06 12:45:32');
