LOCK TABLES `participants` WRITE;
/*!40000 ALTER TABLE `participants` DISABLE KEYS */;
INSERT INTO `participants` VALUES
('040abe68-a853-4cf9-a4ee-61854a77e146','aleksandr-volkov','Александр Волков','Участник 20 сезона','Потомственный маг в седьмом поколении. Владеет техниками работы с энергией, проводит обряды на защиту и привлечение удачи.','Александр Волков — потомственный маг, чьи предки на протяжении семи поколений хранили древние знания и ритуалы.\n\nСпециализируется на защитной магии, снятии негативных воздействий.','https://images.unsplash.com/photo-1624948456761-0f2660d3dc5f?q=85&w=600&auto=format&fit=crop','[\"Маг\",\"Целитель\"]',1,2,'2026-03-06 12:45:32'),
('380febb0-2717-4509-9141-a307cf58066f','marina-svetlova','Марина Светлова','Финалист 18 сезона','Обладает даром ясновидения с раннего детства. Специализируется на поиске пропавших людей и предсказании будущего.','Марина Светлова — одна из сильнейших участниц проекта «Битва экстрасенсов». С детства она видела то, что скрыто от глаз обычных людей.\n\nЗа годы практики Марина провела более 3000 консультаций, помогая людям в самых сложных жизненных ситуациях.','https://images.unsplash.com/photo-1603669388518-beee44ac92de?q=85&w=600&auto=format&fit=crop','[\"Ясновидящая\",\"Экстрасенс\"]',1,1,'2026-03-06 12:45:32'),
('43e56f5a-d61b-4c2a-8530-4a7c009e5bc8','elena-tarasova','Елена Тарасова','Участница 16 сезона','Профессиональный таролог и медиум. Проводит глубинные расклады, помогает разобраться в сложных жизненных ситуациях.','Елена Тарасова — признанный таролог и медиум с многолетним опытом.\n\nОсобое внимание Елена уделяет вопросам любви и отношений.','https://images.pexels.com/photos/7278734/pexels-photo-7278734.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','[\"Ведьма\",\"Таролог\"]',1,3,'2026-03-06 12:45:32'),
('52a3b2ed-0ec2-465d-94f4-095548b5fb0c','natalya-orlova','Наталья Орлова','Финалист 19 сезона','Потомственная ведьма, владеет древними ритуалами славянской магии. Помогает в вопросах любви, семьи и защиты.','Наталья Орлова — потомственная ведьма, чей род восходит к знахаркам Русского Севера.\n\nСпециализируется на любовной магии и защитных ритуалах.','https://images.unsplash.com/photo-1544005313-94ddf0286df2?q=85&w=600&auto=format&fit=crop','[\"Ведьма\",\"Маг\"]',1,5,'2026-03-06 12:45:32'),
('64682033-e28c-459a-b8b2-543071d49d14','igor-petrov','Игорь Петров','Участник 21 сезона','Парапсихолог и экстрасенс с 20-летним стажем. Работает с кармическими связями, прошлыми жизнями.','Игорь Петров — дипломированный парапсихолог. Более 20 лет посвятил изучению паранормальных явлений.\n\nСочетает экстрасенсорное восприятие с научными методами.','https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?q=85&w=600&auto=format&fit=crop','[\"Экстрасенс\",\"Парапсихолог\"]',1,6,'2026-03-06 12:45:32'),
('9823056e-6326-4d1c-a86b-a5b7d3d47d10','vera-kuznetsova','Вера Кузнецова','Участница 17 сезона','Ясновидящая и целительница. Определяет причины болезней на энергетическом уровне.','Вера Кузнецова — ясновидящая и целительница с врождённым даром.\n\nРазработала собственную методику биоэнергетического восстановления.','https://images.unsplash.com/photo-1534528741775-53994a69daeb?q=85&w=600&auto=format&fit=crop','[\"Ясновидящая\",\"Целитель\"]',1,7,'2026-03-06 12:45:32'),
('aacca1c4-4d0c-49e9-9f4b-20c65e9a2206','sergey-morozov','Сергей Морозов','Участник 23 сезона','Потомственный маг, мастер рунической магии. Создаёт индивидуальные обереги и амулеты.','Сергей Морозов — потомственный маг и мастер рунической магии.\n\nВладеет редкими техниками работы с северными рунами.','https://images.unsplash.com/photo-1500648767791-00dcc994a43e?q=85&w=600&auto=format&fit=crop','[\"Маг\",\"Рунолог\"]',1,8,'2026-03-06 12:45:32'),
('addfba1a-3756-4737-8a84-90dafeccc99f','dmitriy-karpov','Дмитрий Карпов','Участник 22 сезона','Практикующий целитель и экстрасенс. Работает с энергетикой человека, проводит диагностику и восстановление биополя.','Дмитрий Карпов — экстрасенс и целитель. Его способности проявились после клинической смерти.\n\nСпециализируется на энергетической диагностике и целительстве.','https://images.pexels.com/photos/7179410/pexels-photo-7179410.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','[\"Экстрасенс\",\"Целитель\"]',1,4,'2026-03-06 12:45:32');
