INSERT INTO `reviews` VALUES
('09a0a844-36d4-4060-b5c2-f21967527d6d','marina-svetlova','Александра Н.','Краснодар, 26 лет','Марина Светлова помогла мне в очень тяжёлый период жизни. Её слова дали мне силы и веру в лучшее.',4,1,'2026-03-06 12:45:32'),
('0e064cae-9df5-4101-bcf4-836fef4332d0','elena-tarasova','Алексей В.','Самара, 43 года','Был настроен скептически, но Елена описала ситуацию с невероятной точностью.',5,1,'2026-03-06 12:45:32'),
('0e82fc8c-9192-4873-a930-e340818ea87c','natalya-orlova','Виктория М.','Краснодар, 37 лет','Обратилась для защиты дочери.',5,1,'2026-03-06 12:45:32'),
('0f0b7cad-e243-4f47-9d16-accc2361fad8','dmitriy-karpov','Сергей Т.','Красноярск, 37 лет','Помог избавиться от панических атак.',5,1,'2026-03-06 12:45:32'),
('10336b57-9660-4553-851b-63865de85cbb','natalya-orlova','Кристина Р.','Екатеринбург, 25 лет','Помогла вернуть любимого.',5,1,'2026-03-06 12:45:32'),
('11fe359f-5039-4466-a279-4cfc25a7b97d','sergey-morozov','Светлана Т.','Воронеж, 37 лет','Определил причину несчастий и провёл защитный ритуал.',5,1,'2026-03-06 12:45:32'),
('136c9fa2-2ec5-467f-95ad-c4012dfe8b73','marina-svetlova','Елена Р.','Казань, 29 лет','Марина увидела проблему сразу. Я была поражена точностью её диагностики. Она описала людей из моего окружения так, будто знала их лично. Рекомендации оказались очень действенными.',5,1,'2026-03-06 12:45:32'),
('14425437-4683-4a5d-8ec7-eee65f2ce4f9','marina-svetlova','Мария Л.','Пермь, 44 года','Обратилась к Марине с хронической проблемой. За два сеанса она помогла разобраться в ситуации.',5,1,'2026-03-06 12:45:32'),
('18762c2b-1f98-40c0-bf73-2452270fb224','aleksandr-volkov','Кристина Л.','Челябинск, 34 года','Александр Волков создал для меня защитный амулет.',4,1,'2026-03-06 12:45:32'),
('222dd0c5-48a8-43c0-a3a8-71f2ad64b02d','sergey-morozov','Виктор Р.','Краснодар, 51 год','Потомственный маг — это чувствуется.',4,1,'2026-03-06 12:45:32'),
('24eb6d5b-7b34-4561-9d40-e9b06920ddde','dmitriy-karpov','Андрей П.','Воронеж, 44 года','Восстановил моё биополе после сильного стресса.',4,1,'2026-03-06 12:45:32'),
('287ad2f8-ea7d-48ec-a69e-730a70c6cad1','aleksandr-volkov','Роман Н.','Казань, 47 лет','Потомственный маг — это чувствуется. Снял негатив с нашего дома за один визит.',5,1,'2026-03-06 12:45:32'),
('2a2685aa-1881-4363-b592-a0e853063acc','vera-kuznetsova','Виктория Н.','Тюмень, 39 лет','Помогла справиться с хронической усталостью.',5,1,'2026-03-06 12:45:32'),
('2ae90e77-3071-4dca-afa0-28ea95cdb3ec','vera-kuznetsova','Ольга Д.','Санкт-Петербург, 37 лет','Удивительный целитель.',5,1,'2026-03-06 12:45:32'),
('2e049d6d-b35e-4a36-84a5-11a35aba691c','elena-tarasova','Светлана А.','Воронеж, 45 лет','Обратилась в сложный период. Передала послание от ушедшего родственника.',5,1,'2026-03-06 12:45:32'),
('2f0b6ed5-8109-4465-b020-82cdf8a5365c','aleksandr-volkov','Вера С.','Омск, 43 года','Александр помог моей маме справиться с тяжёлой ситуацией.',5,1,'2026-03-06 12:45:32'),
('3102860b-8c43-4563-9d2d-5c5b23e8ddf0','marina-svetlova','Виктор П.','Самара, 48 лет','Обратился к Марине с вопросом о пропавшем родственнике. Она дала точные указания, которые помогли в поисках.',5,1,'2026-03-06 12:45:32'),
('3719bde0-edb8-49ea-bf2d-fc42dc93e7aa','dmitriy-karpov','Екатерина Р.','Санкт-Петербург, 33 года','Обратилась с хронической усталостью. Чувствую себя заново рождённой.',5,1,'2026-03-06 12:45:32'),
('372fb262-cdc6-4be5-8d60-745b09029aff','vera-kuznetsova','Ирина Б.','Ростов-на-Дону, 35 лет','Биоэнергетическое восстановление — это невероятное.',5,1,'2026-03-06 12:45:32'),
('3abd83d6-1f0a-45d1-b73f-0dc2a372cc7b','sergey-morozov','Елена В.','Тюмень, 32 года','Создал обереги для моей семьи.',5,1,'2026-03-06 12:45:32'),
('3ba1d444-fca4-4f01-b772-d66b75293cf4','marina-svetlova','Светлана Д.','Тюмень, 39 лет','Марина — удивительный человек. Она не только видит проблему, но и объясняет её корни.',5,1,'2026-03-06 12:45:32'),
('3bb7c8c2-58c1-4fe8-ae93-a9dccaee15a5','dmitriy-karpov','Ольга А.','Ростов-на-Дону, 42 года','После сеанса словно заново родилась.',5,1,'2026-03-06 12:45:32'),
('3e4adaa0-919f-43d8-96c9-4796f269884b','natalya-orlova','Анастасия Л.','Москва, 28 лет','Наталья помогла найти любовь. Встретила мужа через месяц.',5,1,'2026-03-06 12:45:32'),
('4029ef92-ef36-4981-abf6-f562ead36919','elena-tarasova','Кира М.','Пермь, 29 лет','Обращаюсь к ней уже третий год. Ни разу не ошиблась.',5,1,'2026-03-06 12:45:32'),
('40929541-b93a-4ee9-8371-8a2e285d1832','dmitriy-karpov','Михаил К.','Казань, 51 год','Дмитрий — удивительный целитель. Помог восстановить здоровье после операции.',5,1,'2026-03-06 12:45:32'),
